/* @socom-skeleton stub GetThrottleFromSpeed__9CSealCtrlFfi */
float CSealCtrl::GetThrottleFromSpeed(float speed, int axis)
{
	/* 0x2840d0: the throttle that gives a speed (GetSpeedFromThrottle's inverse): forward (0)
	 * and strafe (1) over the seal's maximum motion times its move speed modifier, turn (2)
	 * over the character dynamics' maximum turn rate. ELF: another axis divides by an unset
	 * local (kept as 1 here). */
	CZSealBody* seal = static_cast<CZSealBody *>(m_entity);
	f32 max = 1.0f;
	f32 other;

	if (axis == 1)
	{
		seal->GetMaxXMotion(max, other);
		max *= seal->m_movespeedmod;
	}
	else if (axis == 0)
	{
		seal->GetMaxZMotion(max, other);
		max *= seal->m_movespeedmod;
	}
	else if (axis == 2)
	{
		max = theCharacterDynamics.m_turn_maxRate;
	}

	return speed / max;
}

/* @socom-skeleton stub GetSpeedFromThrottle__9CSealCtrlFfi */
float CSealCtrl::GetSpeedFromThrottle(float throttle, int axis)
{
	/* 0x284020: the speed a throttle gives: forward (0) and strafe (1) scale the seal's
	 * maximum motion (x its move speed modifier), turn (2) the character dynamics' maximum
	 * turn rate. ELF: another axis multiplies an unset local (kept as 0 here). */
	CZSealBody* seal = static_cast<CZSealBody *>(m_entity);
	f32 max = 0.0f;
	f32 other;

	if (axis == 1)
	{
		seal->GetMaxXMotion(max, other);
		max *= seal->m_movespeedmod;
	}
	else if (axis == 0)
	{
		seal->GetMaxZMotion(max, other);
		max *= seal->m_movespeedmod;
	}
	else if (axis == 2)
	{
		max = theCharacterDynamics.m_turn_maxRate;
	}

	return throttle * max;
}

/* @socom-skeleton stub PostMortemPreTick__9CSealCtrlFf */
void CSealCtrl::PostMortemPreTick(float dT)
{
	/* 0x283f20 (CZSealBody::PreTick while dead; ELF returns 1): the pad still drives the
	 * throttles (the death camera's rotate stick), right / left (rising, outside the
	 * weapon menu) ask to move the spectator camera on / back; single player: SELECT+X asks
	 * for a respawn (CZSealBody::PostMortemPreTick). ELF: the pad is not NULL-tested. */
	CZSealBody *seal = static_cast<CZSealBody *>(m_entity);
	CPad *pad = m_padid < 2 ? CInput::m_pads[m_padid] : NULL;
	ThrottlesPreTick(pad, dT);
	MENU_STATE menu = m_menustate;
	seal->m_advance_camera = pad->m_state[static_cast<u8>(PAD_BUTTON::PAD_RIGHT)] == KEY_RISING && menu != stateWeaponSel;
	seal->m_retreat_camera = pad->m_state[static_cast<u8>(PAD_BUTTON::PAD_LEFT)] == KEY_RISING && menu != stateWeaponSel;

	if (theNetwork.m_bNetwork)
	{
		/* port: not written - theVoice +0x11 = 1 (0x283fd0); the port has no network play */
	}
	else if (pad->GetTwoButtons(PAD_BUTTON::PAD_SELECT, PAD_BUTTON::PAD_CROSS))
	{
		seal->m_needs_respawn = true;
	}
}

/* @socom-skeleton stub UpdateAiVisMap__9CSealCtrlFv */
bool CSealCtrl::UpdateAiVisMap()
{
	/* 0x283e60 (CZSealBody::UpdateAiMapLoc on a new cell): the vis map follows the body's
	 * valid AI map location; 0 without a vis map */
	if (m_vismap == NULL)
		return false;

	CAiMapLoc loc = static_cast<CZSealBody *>(m_entity)->m_mapLocValid;
	return CAiVisMap::UpdateDynamicVisMap(m_vismap, loc);
}

/* @socom-skeleton stub SetViewRange__9CSealCtrlFf */
void CSealCtrl::SetViewRange(float range)
{
	/* 0x283e00: the view range (value and decay goal); zero or less: 0.95 of the camera's
	 * mid plane */
	if (!(range <= 0.0f))
	{
		m_visrange.m_value = range;
		m_visrange.m_goal = range;
		return;
	}

	zdb::CCamera* cam = zdb::CWorld::m_world->m_camera;

	if (cam != NULL)
	{
		m_visrange.m_value = 0.95f * cam->m_mid_plane;
		m_visrange.m_goal = m_visrange.m_value;
	}
}

/* @socom-skeleton stub PerturbAimVector__9CSealCtrlFP6CPnt3D */
void CSealCtrl::PerturbAimVector(CPnt3D *dir)
{
	/* 0x283c00 (HandleFireWeapon): the shot direction spread by the body's accuracy: its
	 * right and up axes scaled by the x / y factor plus the size factor times a signed square
	 * of a random -1..1 each */
	CAccuracy *accuracy = &static_cast<CZSealBody *>(m_entity)->m_accuracy;
	CPnt3D up;
	up.x = 0.0f;
	up.y = 1.0f;
	up.z = 0.0f;
	CPnt3D right;
	CPnt3D top;
	dir->Cross(&up, &right, false);
	right.Cross(dir, &top, false);
	f32 r = (f32)(rand() - 0x3fffffff) * 9.313226e-10f;
	r = r < 0.0f ? -(r * r) : r * r;
	right.Scale(accuracy->FactorX + accuracy->Factor * r, &right);
	r = (f32)(rand() - 0x3fffffff) * 9.313226e-10f;
	r = r < 0.0f ? -(r * r) : r * r;
	top.Scale(accuracy->FactorY + accuracy->Factor * r, &top);
	CPnt3D out;
	dir->Add(&right, &out);
	out.Add(&top, dir);
}

